// techIcon maps a project tag to an icon name; a missing key means no icon.
var techIcon = map[string]string{
	"Hono": "hono", "Next.js": "nextjs", "Ansible": "ansible",
	"Docker": "docker", "Git": "git", "Linux": "linux",
	"Python": "python", "TypeScript": "typescript",
	"React": "react", "Electron": "electron",
}

func techIconLookup(tag string) string { return techIcon[tag] }

// LeadTag is the project's primary technology, used for its card icon when the
// project ships no logo of its own. Mirrors the Svelte `technologies[tags[0]]`.
func (p project) LeadTag() string {
	if len(p.Tags) == 0 {
		return ""
	}
	return p.Tags[0]
}

// iconAt renders an icon at an explicit pixel size. Unknown names render
// nothing so a missing icon never breaks a layout.
//
// Tall brand marks (Hono is 256x330) keep their aspect ratio, otherwise a
// square box shears them.
func iconAt(name string, size int) template.HTML {
	dims := fmt.Sprintf(`width="%d" height="%d"`, size, size)

	if body, ok := strokeIcons[name]; ok {
		stroke := strokeColor[name]
		if stroke == "" {
			stroke = "currentColor"
		}
		return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" ` + dims +
			` viewBox="0 0 24 24" fill="none" stroke="` + stroke + `" stroke-width="2" ` +
			`stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ` +
			`class="icon">` + body + `</svg>`)
	}
	if b, ok := brandIcons[name]; ok {
		w, h := viewBox(b.viewBox)
		// Fit inside the box on the longer axis, so a tall mark (Hono is
		// 256x330) gets narrower rather than taller. Otherwise it stretches the
		// badge and breaks the row of otherwise identical-height chips.
		sw, sh := size, size
		if h > w {
			sw = int(float64(size) * w / h)
		} else if w > h {
			sh = int(float64(size) * h / w)
		}
		dims = fmt.Sprintf(`width="%d" height="%d"`, sw, sh)
		return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" ` + dims +
			` viewBox="` + b.viewBox + `" fill="currentColor" aria-hidden="true" ` +
			`class="icon">` + b.body + `</svg>`)
	}
	return ""
}

// viewBox pulls the width and height out of a "0 0 W H" string.
func viewBox(s string) (w, h float64) {
	_, _ = fmt.Sscanf(s, "0 0 %f %f", &w, &h)
	if w == 0 || h == 0 {
		return 1, 1
	}
	return w, h
}
